import { DaprClient } from '@dapr/dapr';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { EventhubService } from '@/config/eventhub/eventhub.service';

@Injectable()
export class PublishMessageService {
  private readonly logger = new AppLogger(PublishMessageService.name);

  private readonly eventhubService: EventhubService;

  public constructor(eventhubService: EventhubService) {
    this.eventhubService = eventhubService;
  }

  public async publishMessage(topic: string, data: object): Promise<void> {
    try {
      const daprClient = new DaprClient();
      const { pubSubName } = this.eventhubService;
      this.logger.debug(
        `Publishing: ${JSON.stringify(data)}, pubSub ${pubSubName} , topicname ${topic}`,
      );
      await daprClient.pubsub.publish(pubSubName, topic, data);
    } catch (error) {
      this.logger.error(`Failed to publish message: ${error.message}`);
      this.logger.error(error);
    }
  }
}

